import{H as e,V as t,et as n,j as r}from"./chunks/framework.ChZHrXbO.js";var i=JSON.parse(`{"title":"视图、存储过程、触发器","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/views-stored-procedures-triggers.md","filePath":"mysql/views-stored-procedures-triggers.md"}`),a={name:`mysql/views-stored-procedures-triggers.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="视图、存储过程、触发器" tabindex="-1">视图、存储过程、触发器 <a class="header-anchor" href="#视图、存储过程、触发器" aria-label="Permalink to “视图、存储过程、触发器”">​</a></h1><h2 id="_1-视图" tabindex="-1">1.视图 <a class="header-anchor" href="#_1-视图" aria-label="Permalink to “1.视图”">​</a></h2><p>视图(View)是一种虚拟存在的表。视图中的数据并不在数据库中实际存在，行和列数据来自定义视图的查询中使用的表，并且是在使用视图时动态生成的。</p><p>通俗的讲，视图只保存了查询的SQL逻辑，不保存查询结果。所以我们在创建视图的时候，主要的工作就落在创建这条SQL查询语句上。</p><h3 id="_1-1-语法" tabindex="-1">1.1 语法 <a class="header-anchor" href="#_1-1-语法" aria-label="Permalink to “1.1 语法”">​</a></h3><p>创建视图</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [OR REPLACE] VIEW 视图名称(列名列表) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SELECT语句[WITH</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">[</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CASCADED|LOCAL] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CHECK</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> OPTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>查看创建视图语句</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VIEW 视图名称;</span></span></code></pre></div><p>查看视图数据</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 视图名称…;</span></span></code></pre></div><p>查看数据中中所有视图</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW FULL TABLES </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 数据库名 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Table_type </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;VIEW&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>修改视图</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [OR REPLACE] VIEW 视图名称(列名列表) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SELECT语句 [WITH </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">[</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CASCADED|LOCAL] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CHECK</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> OPTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];  或</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> VIEW</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 视图名称(列名列表) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SELECT语句 [WITH </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">[</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CASCADED|LOCAL] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CHECK</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> OPTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>删除视图</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">DROP</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> VIEW</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [IF EXISTS] 视图名称[,视图名称];</span></span></code></pre></div><h3 id="_1-2-检查选项" tabindex="-1">1.2 检查选项 <a class="header-anchor" href="#_1-2-检查选项" aria-label="Permalink to “1.2 检查选项”">​</a></h3><p>当使用WITH CHECK OPTION子句创建视图时，MySOL会通过视图检查正在更改的每个行，例如 插入，更新，删除，以使其符合视图的定义。MySQL允许基于另一个视图创建视图，它还会检查依赖视图中的规则以保持一致性。</p><p>视图的插入、删除、更新语句和基本表的语句一致，当执行增删改操作时，实际改变的是基本表中的数据，但是不建议通过视图更改基本表。</p><p>为了确定检查的范围，mysql 提供了两个选项:CASCADED 和 LOCAL，默认值为CASCADED</p><p><strong>cascaded：在对视图进行更删改操作时，会核查该视图及所有直接或间接依赖的视图创建语句中的条件，只有当所有条件</strong>都满足才能够操作成功，例如：</p><ul><li><p><code>create view v1 as select id,name from student where id&lt;=20;</code>因为没有指定WITH CHECK OPTION子句，插入时不会核查条件id&lt;=20，直接插入成功</p></li><li><p><code>create view v2 as select id,name from v1 where id&gt;10 with cascaded check option;</code>插入时会核查v2中的条件id&gt;10和v1中的条件id&lt;=20，只有全部满足时才会插入成功，相当于给v1添加了with cascaded check option子句</p></li><li><p><code>create view v3 as select id,name from v2 where id&lt;=15;</code>由于v3没有指定WITH CHECK OPTION子句，不会核查条件id&lt;=15，但是由于v2指定了with cascaded check option子句，所以会核查v2的条件id&gt;10和v1的条件id&lt;=20;</p></li></ul><p><strong>local：在对视图进行更删改操作时，会核查该视图及所有直接或间接依赖的且使用WITH CHECK OPTION子句的视图创建语句中的条件，只有当所有条件</strong>都满足才能够操作成功，例如：</p><ul><li><p><code>create view v4 as select id,name from student where id&lt;=20;</code>因为没有指定WITH CHECK OPTION子句，插入时不会核查条件id&lt;=20，直接插入成功</p></li><li><p><code>create view v5 as select id,name from v4 where id&gt;10 with local check option;</code>插入时会核查v5中的条件id&gt;10，因为v4中没有使用WITH CHECK OPTION子句，所以不会核查v4中的条件id&lt;=20，也就是说，不会给v4添加with local check option子句</p></li><li><p><code>create view v6 as select id,name from v5 where id&lt;=15;</code>因为没有指定WITH CHECK OPTION子句，插入时不会核查条件id&lt;=15，由于v5使用了with local check option子句，所以会核查v5中的条件id&gt;10，又因为v4中没有使用WITH CHECK OPTION子句，所以不会核查v4中的条件id&lt;=20，也就是说，仅仅核查有with local check option子句的视图中的条件</p></li></ul><h3 id="_1-3-更新及作用" tabindex="-1">1.3 更新及作用 <a class="header-anchor" href="#_1-3-更新及作用" aria-label="Permalink to “1.3 更新及作用”">​</a></h3><p>要使视图可更新，视图中的行与基础表中的行之间<strong>必须存在一对一的关系</strong>，即视图中的每一行必须直接对应基础表中的<strong>唯一一行</strong>，不能有多行映射到视图中的同一行，也不能有视图中的一行映射到基础表中的多行</p><p>如果视图包含以下任何一项，则该视图不可更新或插入：</p><ol><li><p>聚合函数或窗口函数SUM()、MIN()、MAX()、COUNT()等</p></li><li><p>DISTINCT</p></li><li><p>GROUP BY</p></li><li><p>HAVINGA</p></li><li><p>UNION 或者 UNION ALL</p></li></ol><h3 id="_1-4-视图的作用" tabindex="-1">1.4 视图的作用 <a class="header-anchor" href="#_1-4-视图的作用" aria-label="Permalink to “1.4 视图的作用”">​</a></h3><ul><li><p><strong>简单</strong> 视图不仅可以简化用户对数据的理解，也可以简化他们的操作。那些被经常使用的查询可以被定义为视图，从而使得用户不必为以后的操作每次指定全部的条件。</p></li><li><p><strong>安全</strong> 数据库可以授权，但不能授权到数据库特定行和特定的列上。通过视图用户只能查询和修改他们所能见到的数据。</p></li><li><p><strong>数据独立</strong> 视图可帮助用户屏蔽真实表结构变化带来的影响。</p></li></ul>`,31)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};